    end
    else begin
      gbcore_rva_out_PopNB_mioi_bcwt <= ~((~(gbcore_rva_out_PopNB_mioi_bcwt | gbcore_rva_out_PopNB_mioi_biwt))
          | gbcore_rva_out_PopNB_mioi_bdwt);
