// ------------------------------------------------------------------
//  Design Unit:    GBModule_Transpose_Run_Run_fsm
//  FSM Module
// ------------------------------------------------------------------


module Top_GBPartition_GBModule_Transpose_Run_Run_fsm (
  clk, rst, Run_wen, fsm_output
);
  input clk;
  input rst;
  input Run_wen;
  output [1:0] fsm_output;
  reg [1:0] fsm_output;


  // FSM State Type Declaration for GBModule_Transpose_Run_Run_fsm_1
  parameter
    Run_rlp_C_0 = 2'd0,
    while_C_0 = 2'd1,
    while_C_1 = 2'd2,
    while_C_2 = 2'd3;

  reg [1:0] state_var;
  reg [1:0] state_var_NS;


  // Interconnect Declarations for Component Instantiations
  always @(*)
  begin : GBModule_Transpose_Run_Run_fsm_1
    case (state_var)
      while_C_0 : begin
        fsm_output = 2'b01;
        state_var_NS = while_C_1;
      end
      while_C_1 : begin
        fsm_output = 2'b10;
        state_var_NS = while_C_2;
      end
      while_C_2 : begin
        fsm_output = 2'b11;
        state_var_NS = while_C_0;
      end
      // Run_rlp_C_0
      default : begin
        fsm_output = 2'b00;
